SELECT COUNT(*) FROM media_asset
WHERE deleted=0 AND status='ACTIVE'
AND media_type=#{mediaType}
AND usage_type=#{usageType}

SELECT  FROM media_asset
WHERE deleted=0 AND status='ACTIVE'
AND media_type=#{mediaType}
AND usage_type=#{usageType}
ORDER BY created_at DESC,id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT
  (SELECT COUNT(*) FROM profile WHERE avatar_url=#{url})
+ (SELECT COUNT(*) FROM post_media WHERE deleted=0 AND (url=#{url} OR poster_url=#{url}))
+ (SELECT COUNT(*) FROM site_config
   WHERE hero_desktop_video_url=#{url}
      OR hero_mobile_video_url=#{url}
      OR hero_poster_url=#{url}
      OR music_audio_url=#{url}
      OR music_cover_url=#{url}
      OR JSON_SEARCH(page_media_json,'one',#{url}) IS NOT NULL)
